import math

def is_power_of_p_ge2(X, p):
    """Checks if X is p^a where a >= 2."""
    if X <= 1:
        return False

    # Check divisibility by p
    if X % p != 0:
        return False

    # Calculate the exponent a = log_p(X)
    try:
        # Using log base p
        a = round(math.log(X, p))
    except ValueError:
        # Should not happen if X > 1 and p >= 2
        return False

    # Verify it is exactly a power of p
    if p**a != X:
        return False

    return a >= 2

found_triples = []
primes = [2, 3, 5]
M_MAX = 50
N_MAX = 50

for p in primes:
    for m in range(1, M_MAX + 1):
        for n in range(1, N_MAX + 1):
            X = m*m + n
            Y = m + n*n

            # Check conditions
            is_X_power = is_power_of_p_ge2(X, p)
            is_Y_power = is_power_of_p_ge2(Y, p)

            if is_X_power and is_Y_power:
                found_triples.append((m, n, p))

print("Found Triples (m, n, p):")
for triple in found_triples:
    print(triple)
